    if(!String(c.name||'').trim())issues.push({severity:'error',message:'A condition is missing its name.'});
    if(!(c.facts||[]).length)issues.push({severity:'warning',condition:c.name,message:'Condition has no extracted facts.'});
    for(const f of c.facts||[]){
      if(ids.has(f.id))issues.push({severity:'error',condition:c.name,factId:f.id,message:'Duplicate fact ID.'});
      ids.add(f.id);
