      if(![1,2,3].includes(Number(f.tier)))issues.push({severity:'error',condition:c.name,factId:f.id,message:'Fact does not have exactly one valid tier.'});
      if(!String(f.text||'').trim())issues.push({severity:'error',condition:c.name,factId:f.id,message:'Fact text is empty.'});
      if(!String(f.sourceQuote||'').trim())issues.push({severity:'warning',condition:c.name,factId:f.id,message:'Fact has no short verbatim source anchor; NCLEX grounding will fall back to the concise fact text.'});
