    const needle=q.trim().toLowerCase();
    return facts.filter(f=>(bucket==='all'||f.latteBucket===bucket)&&
      (!needle||String(f.text||'').toLowerCase().includes(needle)||String(f.id||'').toLowerCase().includes(needle)||String(f.sourceQuote||'').toLowerCase().includes(needle)));
  },[facts,q,bucket]);
