    <div style={{display:'flex',gap:6,flexWrap:'wrap',alignItems:'center',marginBottom:10}}>
      <input aria-label="Filter facts by text, ID, or source quote" type="text" value={q} onChange={e=>setQ(e.target.value)} placeholder="Filter facts…" style={{flex:'1 1 150px',minWidth:110}}/>
      <button type="button" className={'tier-btn'+(bucket==='all'?' t3 active':'')} aria-pressed={bucket==='all'} onClick={()=>setBucket('all')}>All <b>{facts.length}</b></button>
      {KB_BUCKETS.filter(b=>counts[b]).map(b=><button key={b} type="button" className={'tier-btn'+(bucket===b?' t3 active':'')} aria-pressed={bucket===b} onClick={()=>setBucket(bucket===b?'all':b)}>{b} <b>{counts[b]}</b></button>)}
