    <div style={{fontSize:12,color:'var(--text-dim)',marginBottom:8}}>Click any fact ID to inspect its verbatim anchor, source pointer, and downstream usage.</div>
    {!shown.length&&<div style={{fontSize:14,color:'var(--text-dim)'}}>No facts match this filter.</div>}
    {shown.map(f=><div key={f.id} style={{display:'flex',gap:8,alignItems:'flex-start',padding:'7px 9px',borderRadius:6,border:'1px solid var(--border)',background:'var(--bg-input)',marginBottom:4}}>
      <FactTag factId={f.id}/>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontSize:14,lineHeight:1.5,color:'var(--text)'}}>{f.text}</div>
        <div style={{display:'flex',gap:5,flexWrap:'wrap',marginTop:4,alignItems:'center'}}>
          <span className="fact-bucket-badge">{f.latteBucket}{f.subtype?' \u00b7 '+f.subtype:''}</span>
          <span className={'tier-badge t'+(f.tier||'')}>T{f.tier}</span>
